#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,hashlib,runpy
root=Path('/Users/murphyhoops/Documents/ueotlean-worktrees/core-books-handoff-20261020/path-realization-evidence-20261022')
raw=gzip.decompress(base64.b64decode('',validate=True))
assert hashlib.sha256(raw).hexdigest()=='07ecba689fed2328640c9e80b9f0ec995bb85953ac94d6741d2f858aab959058'
p=root/'CANONICAL_SYNC_01.json'
assert not p.exists() or p.read_bytes()==raw
p.write_bytes(raw)
runpy.run_path(str(root/'sync_canonical_inputs.py'),run_name='__main__')
